-- PREPARADA, NÃO EXECUTADA. Rode checkout-schema-audit.sql e revise o resultado antes.
-- O carrinho do projeto guarda produtos.slug em carrinho_itens.produto_id.
begin;
create extension if not exists pgcrypto;
do $$ begin
 if to_regclass('public.produtos') is null or to_regclass('public.carrinhos') is null or to_regclass('public.carrinho_itens') is null or to_regclass('public.enderecos') is null or to_regclass('public.cupons') is null or to_regclass('public.configuracoes') is null then raise exception 'CHECKOUT_PREREQUISITO_AUSENTE'; end if;
 if not exists(select 1 from information_schema.columns where table_schema='public' and table_name='carrinho_itens' and column_name='produto_id' and data_type in ('text','character varying')) then raise exception 'CHECKOUT_CARRINHO_INCOMPATIVEL: produto_id deve ser slug textual'; end if;
 if not exists(select 1 from information_schema.columns where table_schema='public' and table_name='produtos' and column_name='slug') then raise exception 'CHECKOUT_PRODUTOS_INCOMPATIVEIS: produtos.slug ausente'; end if;
end $$;
create table if not exists public.pedidos (id uuid primary key default gen_random_uuid(),usuario_id uuid not null references auth.users(id),carrinho_id uuid,numero_pedido text not null unique,status text not null default 'aguardando_pagamento',pagamento_status text not null default 'pendente',subtotal numeric(12,2) not null default 0,desconto_cupom numeric(12,2) not null default 0,desconto_pix numeric(12,2) not null default 0,frete numeric(12,2) not null default 0,total numeric(12,2) not null default 0,cupom_codigo text,endereco_id uuid,metodo_pagamento text not null default 'pix',chave_idempotencia uuid not null unique,reserva_expira_em timestamptz,estoque_liberado_em timestamptz,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now(),check(subtotal>=0 and desconto_cupom>=0 and desconto_pix>=0 and frete>=0 and total>=0));
create table if not exists public.pedido_itens (id uuid primary key default gen_random_uuid(),pedido_id uuid not null references public.pedidos(id) on delete cascade,produto_id uuid references public.produtos(id),produto_slug text not null,produto_cor_id uuid references public.produto_cores(id),produto_variacao_id uuid references public.produto_variacoes(id),nome_produto text not null,imagem_produto text,tamanho text,cor text,quantidade integer not null check(quantidade>0),preco_unitario numeric(12,2) not null check(preco_unitario>=0),total numeric(12,2) not null check(total>=0),criado_em timestamptz not null default now());
create table if not exists public.pagamentos (id uuid primary key default gen_random_uuid(),pedido_id uuid not null unique references public.pedidos(id) on delete cascade,provedor text not null default 'mercado_pago',referencia_externa text unique,status text not null default 'pendente',metodo text not null,valor numeric(12,2) not null check(valor>=0),moeda text not null default 'BRL',detalhes jsonb not null default '{}'::jsonb,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists public.pagamento_eventos (id uuid primary key default gen_random_uuid(),provedor text not null default 'mercado_pago',evento_id text not null unique,pedido_id uuid references public.pedidos(id) on delete set null,referencia_externa text,recebido_em timestamptz not null default now(),detalhes jsonb not null default '{}'::jsonb);
create table if not exists public.frete_cep_elegiveis (id uuid primary key default gen_random_uuid(),cep_inicial char(8) not null,cep_final char(8) not null,ativo boolean not null default true,criado_em timestamptz not null default now(),check(cep_inicial~'^[0-9]{8}$' and cep_final~'^[0-9]{8}$' and cep_inicial<=cep_final));
alter table public.pedidos add column if not exists carrinho_id uuid;
alter table public.pedido_itens add column if not exists produto_slug text;
alter table public.cupons add column if not exists inicio_em timestamptz;
alter table public.cupons add column if not exists expira_em timestamptz;
create index if not exists pedidos_usuario_criado_idx on public.pedidos(usuario_id,criado_em desc);
create index if not exists pedido_itens_pedido_idx on public.pedido_itens(pedido_id);
create index if not exists pedido_itens_variacao_idx on public.pedido_itens(produto_variacao_id);
create unique index if not exists pedidos_carrinho_pendente_unico on public.pedidos(carrinho_id) where pagamento_status='pendente' and estoque_liberado_em is null;
alter table public.pedidos enable row level security; alter table public.pedido_itens enable row level security; alter table public.pagamentos enable row level security; alter table public.pagamento_eventos enable row level security; alter table public.frete_cep_elegiveis enable row level security;
grant select on public.pedidos,public.pedido_itens,public.pagamentos to authenticated; grant update on public.pedidos to authenticated;
drop policy if exists "checkout cliente pedidos" on public.pedidos; create policy "checkout cliente pedidos" on public.pedidos for select to authenticated using(usuario_id=(select auth.uid()));
drop policy if exists "checkout cliente itens" on public.pedido_itens; create policy "checkout cliente itens" on public.pedido_itens for select to authenticated using(exists(select 1 from public.pedidos p where p.id=pedido_id and p.usuario_id=(select auth.uid())));
drop policy if exists "checkout cliente pagamentos" on public.pagamentos; create policy "checkout cliente pagamentos" on public.pagamentos for select to authenticated using(exists(select 1 from public.pedidos p where p.id=pedido_id and p.usuario_id=(select auth.uid())));
drop policy if exists "checkout admin pedidos" on public.pedidos; create policy "checkout admin pedidos" on public.pedidos for all to authenticated using((select auth.jwt()->'app_metadata'->>'role')='admin') with check((select auth.jwt()->'app_metadata'->>'role')='admin');

-- Cria pedido com o slug do carrinho, trava o carrinho e as variações em ordem estável.
create or replace function public.criar_pedido_checkout(p_endereco_id uuid,p_cupom text,p_metodo text,p_chave_idempotencia uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid:=auth.uid(); c uuid; o public.pedidos%rowtype; r record; sub numeric:=0; disc numeric:=0; pix numeric:=0; total numeric; pct numeric; cep text; threshold numeric:=250; v uuid; color uuid; stock integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED'; end if; if p_metodo<>'pix' then raise exception 'METODO_NAO_HABILITADO'; end if;
 select id into c from public.carrinhos where usuario_id=u for update; if c is null then raise exception 'CARRINHO_VAZIO'; end if;
 select * into o from public.pedidos where chave_idempotencia=p_chave_idempotencia and usuario_id=u; if found then return jsonb_build_object('pedido_id',o.id,'numero_pedido',o.numero_pedido,'subtotal',o.subtotal,'desconto_cupom',o.desconto_cupom,'desconto_pix',o.desconto_pix,'frete',o.frete,'total',o.total); end if;
 if exists(select 1 from public.pedidos where carrinho_id=c and pagamento_status='pendente' and estoque_liberado_em is null and reserva_expira_em>now()) then raise exception 'PEDIDO_PENDENTE'; end if;
 select regexp_replace(cep,'[^0-9]','','g') into cep from public.enderecos where id=p_endereco_id and usuario_id=u; if cep is null or length(cep)<>8 or not exists(select 1 from public.frete_cep_elegiveis f where f.ativo and cep between f.cep_inicial and f.cep_final) then raise exception 'FRETE_PENDENTE'; end if;
 for r in select ci.produto_id slug,ci.tamanho,ci.cor,ci.quantidade,p.id,p.nome,p.preco,p.preco_promocional,p.imagens from public.carrinho_itens ci join public.produtos p on p.slug=ci.produto_id where ci.carrinho_id=c and p.ativo order by p.id,lower(coalesce(ci.cor,'')),coalesce(ci.tamanho,'') loop select pc.id,pv.id,pv.estoque into color,v,stock from public.produto_cores pc join public.produto_variacoes pv on pv.produto_cor_id=pc.id where pc.produto_id=r.id and lower(btrim(pc.nome))=lower(btrim(r.cor)) and pv.tamanho=r.tamanho for update; if v is null or stock<r.quantidade then raise exception 'ESTOQUE_INDISPONIVEL'; end if; update public.produto_variacoes set estoque=estoque-r.quantidade where id=v; sub:=sub+coalesce(r.preco_promocional,r.preco)*r.quantidade; end loop;
 if sub<=0 then raise exception 'CARRINHO_VAZIO'; end if; select coalesce(nullif(valor,'')::numeric,250) into threshold from public.configuracoes where chave='frete_gratis_acima'; if sub<coalesce(threshold,250) then raise exception 'FRETE_PENDENTE'; end if;
 if nullif(btrim(coalesce(p_cupom,'')),'') is not null then select percentual into pct from public.cupons where lower(btrim(codigo))=lower(btrim(p_cupom)) and ativo and (inicio_em is null or inicio_em<=now()) and (expira_em is null or expira_em>now()); if pct is null then raise exception 'CUPOM_INVALIDO'; end if; disc:=round(sub*pct/100,2); end if;
 pix:=least(2::numeric,greatest(0::numeric,sub-disc)); total:=sub-disc-pix; if total<=0 then raise exception 'VALOR_INVALIDO'; end if;
 insert into public.pedidos(usuario_id,carrinho_id,numero_pedido,subtotal,desconto_cupom,desconto_pix,frete,total,cupom_codigo,endereco_id,metodo_pagamento,chave_idempotencia,reserva_expira_em) values(u,c,'UGC-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)),sub,disc,pix,0,total,nullif(upper(btrim(p_cupom)),''),p_endereco_id,'pix',p_chave_idempotencia,now()+interval '30 minutes') returning * into o;
 for r in select ci.produto_id slug,ci.tamanho,ci.cor,ci.quantidade,p.id,p.nome,coalesce(p.preco_promocional,p.preco) price,p.imagens from public.carrinho_itens ci join public.produtos p on p.slug=ci.produto_id where ci.carrinho_id=c order by p.id loop select pc.id,pv.id into color,v from public.produto_cores pc join public.produto_variacoes pv on pv.produto_cor_id=pc.id where pc.produto_id=r.id and lower(btrim(pc.nome))=lower(btrim(r.cor)) and pv.tamanho=r.tamanho; insert into public.pedido_itens(pedido_id,produto_id,produto_slug,produto_cor_id,produto_variacao_id,nome_produto,imagem_produto,tamanho,cor,quantidade,preco_unitario,total) values(o.id,r.id,r.slug,color,v,r.nome,coalesce(r.imagens->>0,''),r.tamanho,r.cor,r.quantidade,r.price,r.price*r.quantidade); end loop;
 insert into public.pagamentos(pedido_id,metodo,valor) values(o.id,'pix',total); return jsonb_build_object('pedido_id',o.id,'numero_pedido',o.numero_pedido,'subtotal',sub,'desconto_cupom',disc,'desconto_pix',pix,'frete',0,'total',total);
end $$;
revoke all on function public.criar_pedido_checkout(uuid,text,text,uuid) from public,anon; grant execute on function public.criar_pedido_checkout(uuid,text,text,uuid) to authenticated;

-- Finalização idempotente: nunca regride aprovado; reembolso não repõe estoque automaticamente.
create or replace function public.finalizar_pagamento_checkout(p_pedido_id uuid,p_status text,p_referencia text,p_detalhes jsonb default '{}'::jsonb,p_evento_id text default null) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare o public.pedidos%rowtype;i record;s text:=lower(p_status);begin if s not in('approved','rejected','cancelled','expired','pending','in_process','refunded') then raise exception 'STATUS_INVALIDO';end if;if p_evento_id is not null then insert into public.pagamento_eventos(evento_id,pedido_id,referencia_externa,detalhes) values(p_evento_id,p_pedido_id,p_referencia,coalesce(p_detalhes,'{}')) on conflict(evento_id) do nothing;if not found then return;end if;end if;select * into o from public.pedidos where id=p_pedido_id for update;if not found then raise exception 'PEDIDO_NAO_ENCONTRADO';end if;if o.pagamento_status='approved' then if s='refunded' then update public.pedidos set status='reembolsado',pagamento_status='refunded',atualizado_em=now() where id=o.id;end if;return;end if;if o.pagamento_status in('rejected','cancelled','expired','refunded') then return;end if;if s in('pending','in_process') then return;end if;update public.pagamentos set status=s,referencia_externa=coalesce(p_referencia,referencia_externa),detalhes=coalesce(p_detalhes,detalhes),atualizado_em=now() where pedido_id=o.id;if s='approved' then update public.pedidos set status='pago',pagamento_status='approved',atualizado_em=now() where id=o.id;return;end if;update public.pedidos set status=s,pagamento_status=s,atualizado_em=now() where id=o.id;if o.estoque_liberado_em is null then for i in select * from public.pedido_itens where pedido_id=o.id order by produto_variacao_id loop update public.produto_variacoes set estoque=estoque+i.quantidade where id=i.produto_variacao_id;end loop;update public.pedidos set estoque_liberado_em=now() where id=o.id;end if;end $$;
revoke all on function public.finalizar_pagamento_checkout(uuid,text,text,jsonb,text) from public,anon,authenticated;
create or replace function public.expirar_reservas_checkout() returns integer language plpgsql security definer set search_path=public,pg_temp as $$ declare r record;n integer:=0;begin for r in select id from public.pedidos where pagamento_status='pendente' and estoque_liberado_em is null and reserva_expira_em<=now() order by id for update skip locked loop perform public.finalizar_pagamento_checkout(r.id,'expired',null,jsonb_build_object('origem','rotina_expiracao'),'expiracao:'||r.id::text);n:=n+1;end loop;return n;end $$;
revoke all on function public.expirar_reservas_checkout() from public,anon,authenticated;
commit;
